function [Mp_AC, phi_AC, VsClk, vsRegulated] = fcn_regulate_Vs(vsReg, Mp_AC, phi_AC, VsClkRef)
%FCN_REGULATE_VS keeps the AC source voltage v_s at a fixed amplitude and
%phase by correcting Mp_AC and phi_AC.
%   v_s is generated by a power amplifier + transformer, so its amplitude
%   and phase change with the current.
%   The DAC output (amplifier input) is measured on the same PicoScope as v_s, so
%   angle(Vs/Vdac) is the load-dependent shift of amplifier + transformer.
%   Adding phi_AC (known) gives the phase of v_s relative to the internal
%   oscillator, which is also the reference of phi_m of the converter.
%
%   VsClkRef: v_s phasor in the oscillator frame to hold (taken at no load).
%
%   vsReg: struct with the devices (ts, ps4000aDeviceObj, numChannels,
%   probeVoltsPerUnit, idxVs, idxVdac, dtScope, f0) and the tuning
%   (TolV, TolPhi, Alpha, MaxStepM, MaxStepPhi, MaxIter, Settle_s, Mmax, Vmax).
%
%   Returns the Mp_AC/phi_AC applied to the board, the last measured VsClk and
%   whether the tolerances were met.

clip = @(x, lim) min(max(x, -lim), lim);

Mp_AC_start = Mp_AC;
phi_AC_start = phi_AC;
vsRegulated = false;

for it = 1:vsReg.MaxIter

    vsReg.ts.write("Config", struct("wMpAC", Mp_AC));
    vsReg.ts.write("Config", struct("wphi_AC", phi_AC));
    Mp_AC_written = Mp_AC;
    phi_AC_written = phi_AC;
    pause(vsReg.Settle_s);

    [~, ~, channelData, ~] = picoscope_acquisition(vsReg.ps4000aDeviceObj, vsReg.numChannels);
    Vs = fcn_FundamentalPhasor(channelData{vsReg.idxVs} / vsReg.probeVoltsPerUnit(vsReg.idxVs), vsReg.dtScope, vsReg.f0);
    Vdac = fcn_FundamentalPhasor(channelData{vsReg.idxVdac} / vsReg.probeVoltsPerUnit(vsReg.idxVdac), vsReg.dtScope, vsReg.f0);

    % v_s phasor in the internal oscillator frame: removes the random phase
    % of the capture start (via the DAC phasor) and adds the known DAC phase
    VsClk = Vs * conj(Vdac) / abs(Vdac) * exp(1j * phi_AC);
    VsRms = abs(VsClk);
    ePhi = angle(VsClk / VsClkRef);   % > 0 : v_s leads its reference

    fprintf('Vs reg %2d | Mp_AC %.4f phi_AC %+.4f | Vs %5.2f V rms (ref %5.2f) | phase error %+6.2f deg\n', ...
        it, Mp_AC, phi_AC, VsRms, abs(VsClkRef), rad2deg(ePhi));

    if VsRms > vsReg.Vmax
        vsReg.ts.write("Config", struct("wMpAC", Mp_AC_start));
        vsReg.ts.write("Config", struct("wphi_AC", phi_AC_start));
        error('Vs regulation aborted: v_s above %.1f V rms, Mp_AC and phi_AC set back to their values before the regulation.', vsReg.Vmax);
    end

    % End criteria: v_s back to its reference in amplitude and phase
    if abs(VsRms - abs(VsClkRef)) < vsReg.TolV && abs(ePhi) < vsReg.TolPhi
        vsRegulated = true;
        break;
    end

    % Amplitude: proportional correction using the gain V/M
    Mp_AC = min(max(Mp_AC + clip(vsReg.Alpha * (abs(VsClkRef) - VsRms) * Mp_AC / VsRms, vsReg.MaxStepM), 0), vsReg.Mmax);

    % Phase: v_s follows phi_AC one to one (same oscillator as the DAC)
    phi_AC = angle(exp(1j * (phi_AC - clip(vsReg.Alpha * ePhi, vsReg.MaxStepPhi))));   % keep in (-pi, pi]

end

if ~vsRegulated
    % Return the values that are actually applied (the last update was not written)
    Mp_AC = Mp_AC_written;
    phi_AC = phi_AC_written;
    warning('Vs regulation: tolerances not met after %d iterations.', vsReg.MaxIter);
end

end
